/**
* 从 Markdown 内容中解析 H1-H3 标题
* 符合 CommonMark 规范
*/
function parseHeadingsFromMarkdown(markdown) {
	const headings = [];
	if (!markdown) return headings;
	const contentWithoutCodeBlocks = markdown.replace(/```[\s\S]*?```/g, "");
	const headingRegex = /^(#{1,3})\s+(.+?)(?:\s+#+\s*)?$/gm;
	let match;
	let index = 0;
	while ((match = headingRegex.exec(contentWithoutCodeBlocks)) !== null) {
		const level = match[1].length;
		const text = match[2].trim();
		if (text) {
			headings.push({
				id: `nav-heading-${index}`,
				text,
				level
			});
			index++;
		}
	}
	return headings;
}
